def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    after_c_n = 0
    after_c_d = 0
    after_d_n = 0
    after_d_c = 0
    for i in range(1, n):
        prev_me = history[i - 1][0]
        opp_now = history[i][1]
        if prev_me == 'C':
            after_c_n += 1
            if opp_now == 'D':
                after_c_d += 1
        else:
            after_d_n += 1
            if opp_now == 'C':
                after_d_c += 1

    opp_d_streak = 0
    for m, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for m, o in reversed(history):
        if m == 'D':
            my_d_streak += 1
        else:
            break

    opp_c = n - opp_d

    w = n if n < 8 else 8
    rec_opp_d = 0
    rec_opp_c = 0
    for m, o in history[-w:]:
        if o == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1

    rc_n = 0
    rc_d = 0
    rd_n = 0
    rd_c = 0
    recent_start = n - 12
    if recent_start < 1:
        recent_start = 1
    for i in range(recent_start, n):
        prev_me = history[i - 1][0]
        opp_now = history[i][1]
        if prev_me == 'C':
            rc_n += 1
            if opp_now == 'D':
                rc_d += 1
        else:
            rd_n += 1
            if opp_now == 'C':
                rd_c += 1

    strong_d = opp_d * 2 >= n and (opp_c <= 1 or opp_d * 3 >= n * 2)
    unprov_same_high = (cc + cd) >= 6 and cd * 5 >= (cc + cd) * 2
    recent_unprov_high = rc_n >= 3 and rc_d * 10 >= rc_n * 4
    recent_unprov_med = rc_n >= 3 and rc_d * 10 >= rc_n * 3
    rec_high = w >= 8 and rec_opp_d * 3 >= w * 2
    independent = strong_d or recent_unprov_high or unprov_same_high or rec_high

    tolerant = rd_n >= 1 and rd_c * 2 >= rd_n
    exploit = tolerant and (opp_c * 2 >= n or recent_unprov_med)

    if exploit:
        if independent:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'C'

    if last_opp == 'C':
        if independent:
            if last_me == 'D' and opp_d_streak == 0 and not recent_unprov_high:
                return 'C'
            return 'D'

        if last_me == 'D':
            return 'C'

        if (n >= 12 and after_d_n == 0 and rd_n == 0 and opp_d <= 4 and
                opp_c * 5 >= n * 4 and rec_opp_c >= min(6, n)):
            return 'D'

        if opp_c * 3 >= n * 2 and not strong_d:
            return 'C'

        if opp_d >= opp_c or recent_unprov_med:
            return 'D'

        return 'C'

    if independent or opp_d_streak >= 4:
        return 'D'

    if my_d_streak >= 2 and opp_c * 2 >= n and rc_d <= 4:
        return 'C'

    if opp_c * 3 >= n * 2 and opp_d_streak <= 3 and rc_d <= 3:
        return 'C'

    return 'D'
